def icon(x):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICONS[x]+'</svg>'
def nav(active):
 return '<nav class="bottom" aria-label="主导航">'+''.join(f'<button type="button" class="nav-item {"active" if n==active else ""}" data-go="{n}">{icon(i)}<span>{t}</span></button>' for n,i,t in [('overview','home','概览'),('transactions','list','流水'),('credit','card','信用卡'),('settings','settings','设置')])+'</nav>'
def phone(id,title,sub,content):
 return f'<section class="phone" id="{id}" aria-label="{title}设计稿"><div class="status"><span>9:41</span><span class="status-right">▰ ▰ <span class="battery"></span></span></div><header><div><span class="eyebrow">{sub}</span><h2>{title}</h2></div><span class="avatar">本地</span></header><main>{content}</main>{nav(id)}<div class="gesture"></div></section>'
def row(name,meta,amount,currency,ico='grid',kind='',badge=''):
 return f'<div class="transaction"><span class="tx-icon {kind}">{icon(ico)}</span><div class="tx-name"><strong>{name}</strong><small>{meta}</small>{f"<em>{badge}</em>" if badge else ""}</div><div class="tx-amount {kind}"><b>{amount}</b><small>{currency}</small></div></div>'

