css+='''
#overview .hero{padding-top:16px;padding-bottom:13px}#overview .hero-rule{margin-top:12px}#overview .section-title{margin-top:17px}#overview .recent-title{margin-top:19px}#overview .scan-strip{padding-top:12px}
#credit .period-picker{margin-bottom:12px}#credit .credit-total{padding-top:17px;padding-bottom:15px}#credit .credit-total .main-amount{font-size:46px;line-height:1.3}#credit .cny-line{margin-top:13px;padding-top:12px}#credit .coverage{margin-top:12px}#credit .estimate-note{margin-top:10px;margin-bottom:12px}#credit .repayment{padding-top:14px;padding-bottom:10px}#credit .repayment-bottom{margin-top:10px}#credit .section-title{margin-top:17px;margin-bottom:10px}#credit .rate-detail>div{margin:8px 0}
#transactions .date-label{margin-top:16px}#transactions .transaction{min-height:70px}#transactions .list-end{margin-top:17px}
#settings .setting-card{padding-top:16px;padding-bottom:16px}#settings .preview{margin-top:14px}#settings .reminder-row{margin-bottom:15px}#settings .date-rule{margin-bottom:12px}
'''

js=r'''
const $=s=>document.querySelector(s);
for(const [id,val] of [['statement-day',22],['repayment-day',12]]){const e=document.getElementById(id);for(let i=1;i<=31;i++)e.add(new Option(i,i,i===val,i===val));}
let repaymentMonth=1;
function clampedDate(y,m,d){return new Date(Date.UTC(y,m,Math.min(d,new Date(Date.UTC(y,m+1,0)).getUTCDate())))}
function fmt(d,year=false){return (year?d.getUTCFullYear()+'.':'')+String(d.getUTCMonth()+1).padStart(2,'0')+'.'+String(d.getUTCDate()).padStart(2,'0')}
function updateDates(){const s=+$('#statement-day').value,r=+$('#repayment-day').value;const close=clampedDate(2026,5,s),prev=clampedDate(2026,4,s),start=new Date(+prev+86400000),due=clampedDate(2026,5+repaymentMonth,r);$('#preview-cycle').textContent=fmt(start)+' — '+fmt(close);$('#preview-due').textContent=fmt(due,true);const invalid=due<close;$('#date-error').hidden=!invalid;$('#date-error').textContent='还款日早于出账日，请调整日号或选择次月';$('#save-note').hidden=invalid;$('#preview-save').disabled=invalid;$('#save-note').textContent='仅演示日期规则，不保存设置或创建提醒';return {start:fmt(start,true),close:fmt(close,true),due:fmt(due,true),invalid}}
$('#statement-day').onchange=updateDates;$('#repayment-day').onchange=updateDates;
document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{repaymentMonth=+b.dataset.month;document.querySelectorAll('[data-month]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});updateDates()});
$('#preview-save').onclick=()=>{$('#save-note').textContent='已更新本页日期预览 · 未写入账本，未创建提醒'};
document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-account]').forEach(x=>x.classList.toggle('selected',x===b));const credit=b.dataset.account==='credit';$('#credit-list').hidden=!credit;$('#debit-list').hidden=credit;$('#list-title').textContent=credit?'信用卡 · 尾号 4826':'借记卡 · 尾号 7304'});
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{document.getElementById(b.dataset.go).scrollIntoView({behavior:'smooth',block:'center',inline:'center'})});
updateDates();window.designRules={clampedDate,updateDates};
'''
html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>本地记账 · 页面设计与还款日设置</title><style>'+css+'</style></head><body><div class="board" id="design-board"><div class="board-top"><div><h1>让每一笔，清楚一点。</h1><p>本地短信记账 / 页面样式提案 · 账户分开、原币保留、还款有日期</p></div><div class="board-tag">'+icon('shield')+'设计预览 · 全部为合成数据</div></div><div class="board-grid">'+''.join('<div><p class="screen-title">'+label+'</p>'+phone(id,title,sub,content)+'</div>' for id,title,sub,label,content in [('overview','概览','LOCAL LEDGER','概览 / 每月消费与账户',overview),('credit','信用卡','CREDIT ACCOUNT','信用卡 / 本期估算与还款',credit),('transactions','流水','TRANSACTIONS','流水 / 原币交易与状态',transactions),('settings','日期设置','PREFERENCES','设置 / 账单日与还款日',settings)])+'</div><div class="board-footer"><span>暖白底色 · 墨绿强调 · 原币金额优先</span><span>新增概览样式、还款日与提醒仅为设计规划，尚未进入 Android 功能</span></div></div><script>'+js+'</script></body></html>'
# Bundle only the characters used by this document into a local-font WOFF.
font=TTFont('/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc',fontNumber=2)
options=subset.Options();options.flavor='woff';options.desubroutinize=True
sub=subset.Subsetter(options=options);sub.populate(text=html);sub.subset(font);font.flavor='woff'
font.save(OUT/'font-subset.woff')
fontcss="@font-face{font-family:'Ledger Sans';src:url(data:font/woff;base64,"+b64encode((OUT/'font-subset.woff').read_bytes()).decode()+") format('woff');font-weight:100 900;font-display:block}"
html=html.replace('<style>','<style>'+fontcss,1)
license_text=Path('/usr/share/doc/fonts-noto-cjk/copyright').read_text().split('License: SIL-1.1',2)[-1].split('License: GPL-3+')[0]
html=html.replace('</head>','<!-- Embedded Noto Sans CJK SC subset. Copyright 2010-2012 Google Corporation. '+license_text+' -->\n</head>')
(OUT/'boc-ledger-design.html').write_text(html)
print('Created',OUT/'boc-ledger-design.html',len(html.encode()),'bytes')
